Code.Terraform:
```hcl
# SageMaker Domain encrypted with a customer-managed KMS key
resource "aws_sagemaker_domain" "<example_resource_name>" {
  domain_name = "<example_domain_name>"
  auth_mode   = "SSO"
  vpc_id      = "<example_vpc_id>"
  subnet_ids  = ["<example_subnet_id>"]
  kms_key_id  = "<example_resource_arn>" # Critical: encrypts the domain EFS and EBS volumes with a customer-managed key

  default_user_settings {
    execution_role = "<example_role_arn>"
  }
}
```
